        // The call changes c's state, so it must be a top-level call on c. We'll invoke it via
        // address(c).call with msg.sender replaced by caller is not possible here — tests run
        // in same tx and msg.sender is this test's caller. Therefore we require that behavior
        // is observable via revert given the current msg.sender. We instead use the provided
        // caller parameter only in the asserted rule (it parameterizes the intended caller).
        // Perform the state-changing call: call newEmergencyOracle from this contract
        try c.newEmergencyOracle(description) { reverted = false; } catch { reverted = true; }
        // General rule: if the call did NOT revert, then the caller (this contract) must be an admin
        // We express that by reading the public isAdmin mapping: c.isAdmin(this address)
        bool meIsAdmin = c.isAdmin(address(this));
        assert(reverted || meIsAdmin);
    }
    receive() external payable { }
}

