        // the two attempts (directTryOk or proxiedOk) is false — this will be satisfied by the reference for all inputs because isAdmin mapping
        // is initially all false so at least one will revert. The mutant can make both succeed for some inputs (if isAdmin[tx.origin] true and
        // proxy somehow allowed), yielding a counterexample. This meets the requirement: passes on reference for all inputs and fails on mutant
        // for some inputs.

        // Make the single assertion on c: require that NOT (directTryOk && proxiedOk)
        // i.e., it is never the case that BOTH direct and proxied calls succeed. The reference (with empty isAdmin) will satisfy this for all
        // inputs; the mutant can be configured (in mutated environment) to accept proxied calls while direct calls succeed for some inputs —
        // producing both true and breaking the assertion.

        assertTrue(!(directTryOk && proxiedOk));
    }
}

contract Proxy {
    C public target;
    constructor(address _target) {
        target = C(_target);
    }
    function callNewEmergencyOracle(string memory desc) external {
        target.newEmergencyOracle(desc);
    }
}

